logger = Logger("LC")
NEW_CONFIG_REGEX = re.compile("(New configuration applied)".encode())
CUS_DEFAULT_LOGS_PATH = "/home/cus/logs"


def acquire_telnet_and_run_func(telnet_host, telnet_name, func):
    # type: (Tuple[str, int], str, Callable) -> Any
    """
    Try to open Telnet connection and invoke provided function
    :param telnet_host: tuple with IP address and port
    :param telnet_name: name for connection
    :param func: function signature to be invoked after connection is acquired
    :return: Anything that provided function returns
    """
    try:
        with get_telnet_conn(*telnet_host) as conn:  # type: Telnet
            logger.debug("Func = {}. Connection to {}: ({}:{}) acquired".format(func, telnet_name, *telnet_host))
            func(conn)
    except AttributeError:
        logger.debug("Connection closed: {}: ({}:{}).".format(telnet_name, *telnet_host))
    except Exception as err:
        logger.debug("Cannot connect to {}: ({}:{}), reconnecting in 5s".format(telnet_name, *telnet_host))
        logger.debug(err, exc_info=True)
        sleep(5)


def read_very_eager(conn, f_path=None):
    # type: (Telnet, str) -> str
    """
    This function should be only called in Thread as an observer for the data on the telnet connection.
    :param conn: opened Telnet connection
    :param f_path: file path where to save data
    :return: output from Telnet console within the time connection was opened or f_path
    """
    if f_path:
        return _save_output_to_file(conn, f_path)
    return _save_output_to_memory(conn)


def _save_output_to_file(conn, f_path):
    # type: (Telnet, str) -> str
    """Saves data from Telnet console to the file without buffering"""
    with open(f_path, "ab", buffering=0) as output_file:
        while True:
            try:
                output_file.write(conn.read_very_eager())
            except (EOFError, socket.error, AttributeError):
                logger.debug("Connection error [1], {}, {}".format(conn, f_path))
                return f_path
            except Exception as err:
                logger.debug("Connection error [2], {}, {}".format(conn, f_path))
                logger.exception(err)


def _save_output_to_memory(conn):
    # type: (Telnet) -> str
    """Saves data from Telnet console to the memory and returns as a string"""
    _data = []
    while True:
        try:
            read = conn.read_very_eager().decode()
            _data.append(read)
        except (EOFError, socket.error, AttributeError):
            return "".join(_data)


@contextmanager
def get_telnet_conn(host, port):
    # type: (str, int) -> Generator[Telnet, None, None]
    """
    Creates a Telnet connection and closes it at the end. If err happens on closing it is logger and reraised.
    :param host: IP address of Telnet connection
    :param port: port of Telnet connection
    :return: Telnet instance
    """
    conn = Telnet()
    try:
        conn.open(host, port)
        yield conn
    finally:
        try:
            conn.close()
        except Exception as err:
            logger.debug(err, exc_info=True)
            raise


def log_connections(fun):
    # type: (Callable) -> Any
    """Basic decorator to log opened connections before and after decorated function execution"""
    wraps(fun)

    def inner(*args, **kwargs):
        self = args[0]
        logger.debug("Connections before {}".format(fun.__name__))
        logger.debug(pformat(self._telnet_connections))
        ret = fun(*args, **kwargs)
        logger.debug("Connections after {}".format(fun.__name__))
        logger.debug(pformat(self._telnet_connections))
        return ret

    return inner


def get_moler_config(log_dir):
    # type: (str) -> dict
    moler_configuration = {
        "LOGGER": {"PATH": "{}/moler_logs".format(log_dir), "RAW_LOG": True, "DEBUG_LEVEL": "DEBUG"},
        "DEVICES": {
            "CUS": {
                "DEVICE_CLASS": "ta_moler.device.cus.CUS",
                "CONNECTION_HOPS": {
                    "UNIX_LOCAL": {  # from state
                        "WS": {  # to state
                            "execute_command": "ssh",  # via command
                            "command_params": {  # with params
                                "expected_prompt": "ute@.*",
                                "host": "localhost",
                                "login": "ute",
                                "password": "ute",
                            },
                        }
                    },
                    "WS": {
                        "CUS": {
                            "execute_command": "telnet",
                            "command_params":
                            {"expected_prompt": r"^(\s*(\d{2}\.\d{2}:\d{2}:\d{2}\.\d+\|\s*))?CUS>"}},
                        "UNIX_LOCAL": {
                            "execute_command": "exit",
                            "command_params": {
                                "expected_prompt": "moler_bash",
                                # 'expected_prompt': '.*',
                                "timeout": 2,
                            },
                        },
                    },
                    "CUS": {
                        "WS": {
                            "execute_command": "exit_telnet",
                            "command_params": {
                                "expected_prompt": "ute@.*",
                            },
                        }
                    },
                    "WS_ROOT": {"WS": {"execute_command": "exit", "command_params": {"expected_prompt": "ute@.*"}}},
                },
            }
        },
    }
    logger.debug(moler_configuration)
    return moler_configuration


class cus(object):
    TELNET_CONNECTIONS_LOCK = Lock()
    MAIN_OBSERVER_ACTIVE = Event()
    CONFIG_UPDATE_EVENT = Event()

    def __init__(self, log_host, log_port, configuration, **kwargs):
        # type: (str, int, dict, **str) -> None
        """
        Plugin to collect logs from CUS simulator. It connects to executor console, gets information about configured
        CTRLs and starts listening (saving data) from them. It also observers for any configuration changes
        and restarts listeners. At the end it also gathers additional data from general CUS logs location.
        :param log_host: IP address of logger host
        :param log_port: port of logger host
        :param executor_ip: IP address to executor
        :param executor_port: Port to executor
        """
        global logger
        logger = get_net_logger(log_host, log_port, "cus_{}".format(SERVER_HOST))
        self._log_dir = kwargs.pop("log_dir")
        self._configuration = configuration
        self._executor_host = (configuration["executor_ip"], configuration["executor_port"])
        self._telnet_connections = {"active": {}, "to_remove": {}}  # type: Dict[str, dict]
        self._main_loop_futures = []  # type: List[Future]

    def __enter__(self):
        logger.info("inside {} before start".format(path.basename(__file__)))
        self.start()
        logger.info("inside {} after start".format(path.basename(__file__)))

    def start(self):
        load_config(config=get_moler_config(self._log_dir))
        self._start_gathering_logs()
        self._observe_config_updates_and_start_logs_gathering()

    def __exit__(self, exc_type, exc_val, exc_tb):
        logger.info("inside {} before stop".format(path.basename(__file__)))
        self.stop()
        logger.info("inside {} after stop".format(path.basename(__file__)))

    def stop(self):
        self._set_all_events()
        self._stop_main_loop()
        self._copy_additional_log_files()
        DeviceFactory.remove_all_devices()
        moler_clear()
        self._clear_main_events()

    def _stop_main_loop(self):
        # type: () -> None
        """Stop main loop and get results from corresponding threads"""
        self.MAIN_OBSERVER_ACTIVE.set()
        self.CONFIG_UPDATE_EVENT.set()
        try:
            for future in as_completed(self._main_loop_futures, timeout=10):
                future.result()
        except Exception as err:
            logger.debug(err)
            logger.debug(self._main_loop_futures)
            self.main_loop_executor.shutdown(False)
        else:
            self.main_loop_executor.shutdown()
            logger.debug("Main loop closed")
        if self._configuration["sosreport"]:
            collect_sos_report("cus", self._log_dir, logger)

    @log_connections
    def _start_gathering_logs(self):
        # type: () -> None
        """Gets CUS CTRLs info from Executor console and start gatherers"""
        executor_config_list = self._get_cus_config_list()
        ctrls_info = self._get_cus_ctrls_section(executor_config_list)
        if ctrls_info:
            logger.debug(pformat(ctrls_info))
            self._create_listeners_per_ctrl(ctrls_info)

    @staticmethod
    def _get_cus_ctrls_section(executor_config_list):
        if "ctrl" not in executor_config_list:
            logger.debug("No CTRL section, nothing to gather")
            return
        return executor_config_list["ctrl"]

    def _get_cus_config_list(self):
        # type: () -> Dict[str, Dict[str, str]]
        """Reads config info from CUS-Executor and returns dictionary with CTRL ids and IPs"""
        with self._get_executor("CUS") as cus_executor:
            config_list = cus_executor.get_cmd("config_list", cmd_params={})
            executor_config_list = config_list(timeout=10)
        return executor_config_list

    def _create_listeners_per_ctrl(self, ctrls_info):
        # type: (Dict[str, Dict[str, str]]) -> None
        """Create thread for each CTRL gatherer and starts them"""
        executor = ThreadPoolExecutor(max_workers=len(ctrls_info))
        for ctrl_id, ctrl_params in ctrls_info.items():
            gatherer = Gatherer("CTRL-{}".format(ctrl_id), ctrl_params, self._log_dir)
            gatherer.future = executor.submit(gatherer.start)
            self._set_connection_data(executor=executor, gatherer=gatherer)
            logger.debug("New gatherer created: {}".format(self._telnet_connections["active"][executor][-1]))

    def _set_connection_data(self, executor, gatherer, _type="active"):
        # type: (ThreadPoolExecutor, Gatherer, str) -> None
        """Thread-safe update for internal dictionary with information about opened listeners"""
        with self.TELNET_CONNECTIONS_LOCK:
            if executor not in self._telnet_connections[_type]:
                self._telnet_connections[_type][executor] = []
            self._telnet_connections[_type][executor].append(gatherer)
        logger.debug(pformat(self._telnet_connections))

    @contextmanager
    def _get_executor(self, state=None):
        # type: (Optional[str]) -> device
        """Gets moler device and optionally changes it state to requested"""
        try:
            executor = DeviceFactory.get_device("CUS")
            if state:
                executor.goto_state(state)
            yield executor
        except Exception as err:
            logger.debug(err, exc_info=True)
            raise

    def _set_all_events(self):
        # type: () -> None
        """Set stop event for each gatherer"""
        for _type in self._telnet_connections:
            self._set_events(_type)

    def _set_events(self, _type):
        # type: (str) -> None
        for executor, gatherers in self._telnet_connections[_type].items():
            for gatherer in gatherers:
                logger.debug("Set stop event for gatherer: {}".format(gatherer))
                gatherer.set_stop_event()

    @log_connections
    def _stop_gatherers(self, _type="to_remove"):
        # type: (str) -> None
        """Stops log listeners from internal dictionary from given type."""
        for executor in list(self._telnet_connections[_type]):
            self._stop_gatherers_on_executor(_type, executor)
            self._remove_executor_from_connections(_type, executor)

    def _stop_gatherers_on_executor(self, _type, executor):
        # type: (str, ThreadPoolExecutor) -> None
        for gatherer in self._telnet_connections[_type][executor]:
            gatherer.stop()
            gatherer.future.result()
            logger.debug("Gatherer work has finished: {}".format(gatherer))

    def _remove_executor_from_connections(self, _type, executor):
        # type: (str, ThreadPoolExecutor) -> None
        executor.shutdown()
        with self.TELNET_CONNECTIONS_LOCK:
            del self._telnet_connections[_type][executor]

    def _move_active_gatherers_to__to_remove__(self):
        # type: () -> None
        """Moves all active Telnet connection except the main_loop to the 'to_remove' part so it can be stopped
        and removed securely"""
        with self.TELNET_CONNECTIONS_LOCK:
            self._telnet_connections["to_remove"] = self._telnet_connections["active"]
            self._telnet_connections["active"] = {}

    def _observe_config_updates_and_start_logs_gathering(self):
        # type: () -> None
        """Sets the main loop observer for config update and the second to restart logs gatherers"""
        self.main_loop_executor = ThreadPoolExecutor(max_workers=2, thread_name_prefix="main_threads_")
        self._start_main_observer_thread()
        self._start_gatherers_restarter_thread()

    def _start_gatherers_restarter_thread(self):
        # type: () -> None
        future = self.main_loop_executor.submit(
            self.__restart_logs_gathering,
        )
        self._main_loop_futures.append(future)

    def _start_main_observer_thread(self):
        # type: () -> None
        future = self.main_loop_executor.submit(self._observer_for_config_updates)
        self._main_loop_futures.append(future)

    def __observer_for_config_updates(self, conn):
        # type: (Telnet) -> None
        while not self.MAIN_OBSERVER_ACTIVE.is_set():
            expect_result = self._expect_configuration_update(conn)
            self._set_config_update_event_if_config_occurred(expect_result)

    def _observer_for_config_updates(self):
        # type: () -> None
        """Observer for 'config update' executed by user on Executor console"""
        while not self.MAIN_OBSERVER_ACTIVE.is_set():
            acquire_telnet_and_run_func(self._executor_host, "Executor", self.__observer_for_config_updates)

    @staticmethod
    def _expect_configuration_update(conn):
        # type: (Telnet) -> tuple
        return conn.expect([NEW_CONFIG_REGEX], timeout=5)

    def _set_config_update_event_if_config_occurred(self, expect_result):
        # type: (tuple) -> None
        if expect_result[0] == 0:
            logger.debug("New configuration found. Setting CONFIG_UPDATE_EVENT to reset gatherers")
            self.CONFIG_UPDATE_EVENT.set()
        else:
            logger.debug("Timeout, no new config")

    def __restart_logs_gathering(self):
        # type: () -> None
        """Restarts gathering logs if 'config update' occurred and main observer is still active"""
        while True:
            try:
                self._wait_for_config_update_event()
                self._move_active_gatherers_to__to_remove__()
                self._stop_gatherers()
                if self.MAIN_OBSERVER_ACTIVE.is_set():
                    break
                self._start_gathering_logs()
                self._clear_config_update_event()
            except Exception as err:
                logger.debug(err, exc_info=True)

    def _clear_config_update_event(self):
        if not self.MAIN_OBSERVER_ACTIVE.is_set():
            self.CONFIG_UPDATE_EVENT.clear()

    def _wait_for_config_update_event(self):
        logger.debug("Waiting for event to be set")
        self.CONFIG_UPDATE_EVENT.wait()
        logger.debug("Event has been set")

    def _stop_all_gatherers(self):
        # type: () -> None
        """Stops all gatherers and main observer listener"""
        for _type in ["active", "to_remove"]:
            self._stop_gatherers(_type)

    def _copy_additional_log_files(self):
        if not path.exists(CUS_DEFAULT_LOGS_PATH):
            return
        for file_name in self._get_direct_cus_logs():
            copy(file_name, self._log_dir)

    @staticmethod
    def _get_direct_cus_logs():
        for file_name in listdir(CUS_DEFAULT_LOGS_PATH):
            f_path = path.join(CUS_DEFAULT_LOGS_PATH, file_name)
            if not path.isdir(f_path):
                yield f_path

    def _clear_main_events(self):
        self.MAIN_OBSERVER_ACTIVE.clear()
        self.CONFIG_UPDATE_EVENT.clear()


class Gatherer(object):
    def __init__(self, ctrl_name, ctrl_params, log_dir):
        # type: (str, dict, str) -> None
        """
        Gatherer class that connects to the telnet and saves all console output to the file.
        :param ctrl_name: Name of CTRL that gatherer is connecting to
        :param ctrl_params: IP address and port of CTRL to connect to
        :param log_dir: Directory where Telnet console should be stored
        """
        self._ctrl_name = ctrl_name
        self._ctrl_addr = self._get_ctrl_addr(ctrl_params)
        self._log_dir = log_dir
        self._stop_event = Event()
        self._connection = None
        self._future = None

    def start(self):
        # type: () -> None
        """Opens telnet connection and start saving its output to the file"""
        self._create_connection_and_save_data()

    def stop(self):
        # type: () -> None
        """Closes telnet connection to stop gatherer"""
        self._stop_event.set()
        self._connection.close()
        logger.debug("Stopped {}".format(self))

    def set_stop_event(self):
        # type: () -> None
        """Set stop event for gatherer so upon closing Telnet it doesn't reconnect"""
        self._stop_event.set()

    def save_connection_and_save_to_file(self, conn, f_path):
        self._connection = conn
        read_very_eager(conn, f_path)

    @property
    def future(self):
        # type: () -> Optional[Future]
        """Property to get _future attribute"""
        return self._future

    @future.setter
    def future(self, future):
        # type: (Future) -> None
        """Property to set _future attribute"""
        self._future = future

    def _create_connection_and_save_data(self):
        # type: () -> None
        while not self._stop_event.is_set():
            acquire_telnet_and_run_func(
                self._ctrl_addr,
                self._ctrl_name,
                partial(self.save_connection_and_save_to_file, f_path=path.join(self._log_dir, self._ctrl_name)),
            )

    def __repr__(self):
        # type: () -> str
        return "Gatherer - {}: Host: {}; Connection: {}; Event status: {}".format(
            self._ctrl_name, self._ctrl_addr, self._connection, self._stop_event.is_set()
        )

    def _get_ctrl_addr(self, ctrl_info):
        # type: (dict) -> Tuple[str, int]
        def _is_enbsim():
            return ctrl_info.get("hardware_platform", None) == "ENBSIM"

        return ctrl_info["ip_addr"], 8498 + (int(self._ctrl_name.strip("CTRL-")) if _is_enbsim() else 0)


